    <script>
        function generatePromptCard() {
            const product = document.getElementById('product').value.trim() || "Product";
            const surface = document.getElementById('surface').value;
            const lighting = document.getElementById('lighting').value;
            const angle = document.getElementById('angle').value;
            const mood = document.getElementById('mood').value;

            // Generate composition tags for chips
            const surfaceName = document.getElementById('surface').options[document.getElementById('surface').selectedIndex].text;
            const lightingName = document.getElementById('lighting').options[document.getElementById('lighting').selectedIndex].text;
            const angleName = document.getElementById('angle').options[document.getElementById('angle').selectedIndex].text;

            const chips = [angleName, surfaceName, lightingName];
            const chipContainer = document.getElementById('chip-container');
            chipContainer.innerHTML = '';
            chips.forEach(chipText => {
                const span = document.createElement('span');
                span.className = 'chip';
                span.innerText = chipText;
                chipContainer.appendChild(span);
            });

            // Construct prompt sentence
            const prompt = `${angle}, featuring a ${product}. The product is positioned elegantly on a ${surface}. Illuminated by ${lighting}. Atmosphere is ${mood} --ar 4:5 --v 6.0`;

            document.getElementById('prompt-text').value = prompt;
            document.getElementById('card-product-title').innerText = product;

            // Contrast check logic
            const warningBox = document.getElementById('warning-box');
            const isDarkProduct = /dark|black|navy|charcoal|chocolate|slate/i.test(product);
            const isLightProduct = /light|white|cream|beige|silver|pastel/i.test(product);
            const isDarkSurface = /dark|marble|pool/i.test(surface);
            const isLightSurface = /concrete|oak|sand/i.test(surface);

            if (isDarkProduct && isDarkSurface) {
                document.getElementById('warning-text').innerText = "Contrast Warning: Dark object on dark surface detected. Consider using backlighting or rim light adjustment to keep product distinct.";
                warningBox.classList.add('visible');
            } else if (isLightProduct && isLightSurface) {
                document.getElementById('warning-text').innerText = "Contrast Warning: Light object on light surface detected. Separation shadows or negative fill might be required to ensure clean edge definition.";
                warningBox.classList.add('visible');
            } else {
                warningBox.classList.remove('visible');
            }

            // Reveal prompt card elements
            document.getElementById('output-section').style.display = 'flex';
            document.getElementById('prompt-card').style.display = 'block';

            // Smooth scroll to view
            document.getElementById('prompt-card').scrollIntoView({ behavior: 'smooth' });
        }

        function copyPrompt() {
            const promptText = document.getElementById('prompt-text').value;
            navigator.clipboard.writeText(promptText).then(() => {
                showToast("Prompt copied!");
            });
        }

        function exportCardAsJSON() {
            const data = {
                product: document.getElementById('card-product-title').innerText,
                prompt: document.getElementById('prompt-text').value,
                timestamp: new Date().toISOString()
            };
            const jsonString = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(data, null, 2));
            const downloadAnchor = document.createElement('a');
            downloadAnchor.setAttribute("href", jsonString);
            downloadAnchor.setAttribute("download", `${data.product.toLowerCase().replace(/\s+/g, '-')}-prompt.json`);
            document.body.appendChild(downloadAnchor);
            downloadAnchor.click();
            downloadAnchor.remove();
        }

        function showToast(message) {
            const toast = document.getElementById('toast');
            toast.innerText = message;
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 2000);
        }
    </script>
</body>
</html>


