<body>

<div class="container">
    <header>
        <h1>Prompt Card Studio</h1>
        <p>Create structured product photo prompts offline.</p>
    </header>

    <div class="studio-card">
        <div class="form-group">
            <label for="product">Product</label>
            <input type="text" id="product" value="Ceramic coffee mug">
        </div>
        <div class="form-group">
            <label for="surface">Surface</label>
            <select id="surface">
                <option value="polished dark marble tabletop">Dark Marble</option>
                <option value="raw light concrete block">Light Concrete</option>
                <option value="natural oak wood">Oak Wood</option>
            </select>
        </div>
        <div class="form-group">
            <label for="lighting">Lighting</label>
            <select id="lighting">
                <option value="dramatic side lighting">Side Light</option>
                <option value="soft golden hour window light">Golden Hour</option>
                <option value="high-key studio lighting">Studio Light</option>
            </select>
        </div>
        <div class="form-group">
            <label for="angle">Angle</label>
            <select id="angle">
                <option value="Eye-level macro close-up">Macro Close-Up</option>
                <option value="Low-angle heroic product shot">Heroic Low Angle</option>
                <option value="Flat-lay top-down view">Top Down</option>
            </select>
        </div>
        <button id="generate-btn">Generate Prompt Card</button>
    </div>

    <div id="prompt-card-wrapper">
        <div class="prompt-card">
            <h2 id="card-title">Product Shot</h2>
            <div id="chip-area"></div>
            <div id="warning-box" class="warning"></div>
            <textarea id="prompt-output"></textarea>
            <div class="actions">
                <button id="copy-btn">Copy</button>
                <button id="export-btn">Export</button>
            </div>
        </div>
    </div>
</div>

<script>
    const generateBtn = document.getElementById('generate-btn');
    const productInput = document.getElementById('product');
    const surface = document.getElementById('surface');
    const lighting = document.getElementById('lighting');
    const angle = document.getElementById('angle');
    const wrapper = document.getElementById('prompt-card-wrapper');
    const chipArea = document.getElementById('chip-area');
    const warningBox = document.getElementById('warning-box');
    const promptOutput = document.getElementById('prompt-output');
    const cardTitle = document.getElementById('card-title');

    generateBtn.addEventListener('click', () => {
        const product = productInput.value.trim() || 'Product';
        cardTitle.textContent = product;

        while (chipArea.firstChild) {
            chipArea.removeChild(chipArea.firstChild);
        }

        [angle, surface, lighting].forEach(el => {
            const chip = document.createElement('span');
            chip.classList.add('chip');
            chip.textContent = el.options[el.selectedIndex].text;
            chipArea.appendChild(chip);
        });

        promptOutput.value = `${angle.value}, featuring a ${product} on a ${surface.value}. Lit by ${lighting.value}.`;

        if (product.toLowerCase().includes('dark') && surface.value.includes('dark')) {
            warningBox.style.display = 'block';
            warningBox.textContent = 'Low contrast warning: Dark on dark.';
        } else {
            warningBox.style.display = 'none';
        }

        wrapper.style.display = 'block';
    });

    document.getElementById('copy-btn').addEventListener('click', () => {
        navigator.clipboard.writeText(promptOutput.value);
    });

    document.getElementById('export-btn').addEventListener('click', () => {
        const blob = new Blob([promptOutput.value], {type: 'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'prompt.txt';
        a.click();
    });
</script>
</body>
</html>


