    <div class="toast" id="toast">Copied to clipboard!</div>

    <script>
        const generateBtn = document.getElementById('generate-btn');
        const exportAllBtn = document.getElementById('export-all-btn');
        const deckContainer = document.getElementById('deck-container');
        const toast = document.getElementById('toast');

        let studioDeckData = [];

        generateBtn.addEventListener('click', () => {
            const productVal = document.getElementById('product').value.trim() || "Product Object";

            const surfaceSelect = document.getElementById('surface');
            const surfaceText = surfaceSelect.options[surfaceSelect.selectedIndex].text;
            const surfaceValue = surfaceSelect.value;

            const lightingSelect = document.getElementById('lighting');
            const lightingText = lightingSelect.options[lightingSelect.selectedIndex].text;
            const lightingValue = lightingSelect.value;

            const angleSelect = document.getElementById('angle');
            const angleText = angleSelect.options[angleSelect.selectedIndex].text;
            const angleValue = angleSelect.value;

            const moodSelect = document.getElementById('mood');
            const moodText = moodSelect.options[moodSelect.selectedIndex].text;
            const moodValue = moodSelect.value;

            // Generate full clean prompt text
            const fullPromptStr = `${angleValue}, featuring a ${productVal}. The product is positioned elegantly on a ${surfaceValue}. Illuminated by ${lightingValue}. Atmosphere is ${moodValue} --ar 4:5 --v 6.0`;

            // Calculate Readability / Contrast Analysis score
            let score = 95;
            let note = "Excellent contrast and asset readability guaranteed.";

            const isDarkProduct = /dark|black|navy|charcoal|chocolate|slate/i.test(productVal);
            const isLightProduct = /light|white|cream|beige|silver|pastel/i.test(productVal);
            const isDarkSurface = /dark|marble|pool/i.test(surfaceValue);
            const isLightSurface = /concrete|oak|sand/i.test(surfaceValue);

            if (isDarkProduct && isDarkSurface) {
                score = 55;
                note = "Low contrast: Dark item on dark floor asset profile. Separation may suffer.";
            } else if (isLightProduct && isLightSurface) {
                score = 60;
                note = "Low contrast: Light item on light floor asset profile. Edge detail might bleed.";
            }

            // Create memory reference object for export ecosystem tracking
            const cardDataReference = {
                id: crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(),
                product: productVal,
                surface: surfaceText,
                lighting: lightingText,
                angle: angleText,
                mood: moodText,
                readabilityScore: score,
                contrastNotes: note,
                promptText: fullPromptStr
            };

            studioDeckData.unshift(cardDataReference);

            // Construct DOM node card structure natively without innerHTML injections
            const cardFrame = document.createElement('div');
            cardFrame.classList.add('prompt-card');

            const titleNode = document.createElement('div');
            titleNode.classList.add('card-title');
            titleNode.textContent = productVal;
            cardFrame.appendChild(titleNode);

            const chipContainerNode = document.createElement('div');
            chipContainerNode.classList.add('chip-container');

            [angleText, surfaceText, lightingText, moodText].forEach(textString => {
                const individualChip = document.createElement('span');
                individualChip.classList.add('chip');
                individualChip.textContent = textString;
                chipContainerNode.appendChild(individualChip);
            });
            cardFrame.appendChild(chipContainerNode);

            const scoreDisplayNode = document.createElement('div');
            scoreDisplayNode.classList.add('score-display');
            if (score >= 90) {
                scoreDisplayNode.classList.add('score-good');
            } else {
                scoreDisplayNode.classList.add('score-warning');
            }
            scoreDisplayNode.textContent = `Readability Score: ${score}/100 — ${note}`;
            cardFrame.appendChild(scoreDisplayNode);

            const textareaNode = document.createElement('textarea');
            textareaNode.classList.add('prompt-editable');
            textareaNode.spellcheck = false;
            textareaNode.value = fullPromptStr;

            // Listen to real-time manual text edit adjustments to keep variables consistent inside dataset references
            textareaNode.addEventListener('input', (e) => {
                cardDataReference.promptText = e.target.value;
            });
            cardFrame.appendChild(textareaNode);

            const actionRowNode = document.createElement('div');
            actionRowNode.classList.add('card-actions');

            const copyButtonNode = document.createElement('button');
            copyButtonNode.classList.add('btn-card', 'btn-copy');
            copyButtonNode.textContent = "Copy Prompt";
            copyButtonNode.addEventListener('click', () => {
                // Ensure dynamic extraction reads current viewport string content instead of historical cache string values
                navigator.clipboard.writeText(textareaNode.value).then(() => {
                    toast.classList.add('show');
                    setTimeout(() => {
                        toast.classList.remove('show');
                    }, 2000);
                });
            });

            const removeButtonNode = document.createElement('button');
            removeButtonNode.classList.add('btn-card', 'btn-remove');
            removeButtonNode.textContent = "Remove Card";
            removeButtonNode.addEventListener('click', () => {
                cardFrame.remove();
                const elementIndex = studioDeckData.findIndex(item => item.id === cardDataReference.id);
                if (elementIndex !== -1) {
                    studioDeckData.splice(elementIndex, 1);
                }
            });

            actionRowNode.appendChild(copyButtonNode);
            actionRowNode.appendChild(removeButtonNode);
            cardFrame.appendChild(actionRowNode);

            deckContainer.insertBefore(cardFrame, deckContainer.firstChild);
        });

        exportAllBtn.addEventListener('click', () => {
            const dataString = JSON.stringify(studioDeckData, null, 2);
            const dynamicBlob = new Blob([dataString], { type: 'application/json' });
            const temporaryObjectUrl = URL.createObjectURL(dynamicBlob);

            const shadowAnchorElement = document.createElement('a');
            shadowAnchorElement.href = temporaryObjectUrl;
            shadowAnchorElement.download = 'studio-prompt-deck-export.json';

            document.body.appendChild(shadowAnchorElement);
            shadowAnchorElement.click();

            document.body.removeChild(shadowAnchorElement);
            URL.revokeObjectURL(temporaryObjectUrl);
        });
    </script>
</body>
</html>


